+type Node = TextNode | ValueNode | BlockNode;
+
+interface TextNode { type: "text"; value: string }
+interface ValueNode { type: "value"; path: string; escaped: boolean }
+interface BlockNode {
+  type: "block";
+  kind: "if" | "each";
+  path: string;
+  body: Node[];
+  alternate?: Node[];
+}
+
+interface Frame {
+  block: BlockNode;
+  nodes: Node[];
+  elseSeen: boolean;
+}
+
+interface Context {
+  root: unknown;
+  value: unknown;
+  index?: number;
+}
+
+function location(source: string, offset: number): string {
+  const before = source.slice(0, offset);
+  return `line ${before.split("\n").length}, column ${offset - before.lastIndexOf("\n")}`;
+}
+
+function parseError(source: string, offset: number, message: string): never {
+  throw new Error(`${message} at ${location(source, offset)}`);
+}
+
+function parse(template: string): Node[] {
+  const root: Node[] = [];
+  let nodes = root;
+  const stack: Frame[] = [];
+  let cursor = 0;
+  const token = /\{\{\{[\s\S]*?\}\}\}|\{\{[\s\S]*?\}\}/g;
+
+  for (let match; (match = token.exec(template)); ) {
+    if (match.index > cursor) nodes.push({ type: "text", value: template.slice(cursor, match.index) });
+    cursor = token.lastIndex;
+    const raw = match[0];
+    const triple = raw.startsWith("{{{");
+    const content = raw.slice(triple ? 3 : 2, triple ? -3 : -2).trim();
+
+    if (content.startsWith("!")) continue;
+    if (triple) {
+      if (!content) parseError(template, match.index, "Empty interpolation");
+      nodes.push({ type: "value", path: content, escaped: false });
+      continue;
+    }
+    if (content.startsWith("#")) {
+      const parts = content.slice(1).trim().split(/\s+/);
+      const [kind, ...pathParts] = parts;
+      if ((kind !== "if" && kind !== "each") || pathParts.length !== 1) {
+        parseError(template, match.index, `Unknown or malformed block '${content}'`);
+      }
+      const block: BlockNode = { type: "block", kind, path: pathParts[0], body: [] };
+      nodes.push(block);
+      stack.push({ block, nodes, elseSeen: false });
+      nodes = block.body;
+      continue;
+    }
+    if (content === "else") {
+      const frame = stack.at(-1);
+      if (!frame) parseError(template, match.index, "'else' outside a block");
+      if (frame.elseSeen) parseError(template, match.index, "Duplicate 'else'");
+      frame.elseSeen = true;
+      frame.block.alternate = [];
+      nodes = frame.block.alternate;
+      continue;
+    }
+    if (content.startsWith("/")) {
+      const kind = content.slice(1).trim();
+      const frame = stack.at(-1);
+      if (!frame) parseError(template, match.index, `Unexpected closing block '${kind}'`);
+      if (kind !== frame.block.kind) parseError(template, match.index, `Mismatched closing block '${kind}', expected '${frame.block.kind}'`);
+      stack.pop();
+      nodes = frame.nodes;
+      continue;
+    }
+    if (!content) parseError(template, match.index, "Empty interpolation");
+    nodes.push({ type: "value", path: content, escaped: true });
+  }
+  if (cursor < template.length) nodes.push({ type: "text", value: template.slice(cursor) });
+  const unclosed = stack.at(-1);
+  if (unclosed) parseError(template, template.length, `Unclosed '${unclosed.block.kind}' block`);
+  return root;
+}
+
+function getProperty(value: unknown, key: string): unknown {
+  if (value === null || value === undefined || (typeof value !== "object" && typeof value !== "function")) return undefined;
+  return (value as Record<string, unknown>)[key];
+}
+
+function lookup(value: unknown, path: string): unknown {
+  return path.split(".").reduce((result, key) => getProperty(result, key), value);
+}
+
+function resolve(path: string, context: Context): unknown {
+  if (path === "this") return context.value;
+  if (path === "@index") return context.index;
+  const local = lookup(context.value, path);
+  return local === undefined ? lookup(context.root, path) : local;
+}
+
+function scalar(value: unknown): string {
+  if (value === undefined || value === null) return "";
+  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean" || typeof value === "bigint") return String(value);
+  throw new Error(`Cannot render ${typeof value} as scalar text`);
+}
+
+function escapeHtml(value: string): string {
+  return value.replace(/[&<>"']/g, character => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character]!);
+}
+
+function truthy(value: unknown): boolean {
+  return !(value === "" || value === 0 || value === false || value === null || value === undefined || (Array.isArray(value) && value.length === 0));
+}
+
+function renderNodes(nodes: Node[], context: Context): string {
+  return nodes.map(node => {
+    if (node.type === "text") return node.value;
+    if (node.type === "value") {
+      const value = scalar(resolve(node.path, context));
+      return node.escaped ? escapeHtml(value) : value;
+    }
+    const value = resolve(node.path, context);
+    if (node.kind === "if") return renderNodes(truthy(value) ? node.body : node.alternate ?? [], context);
+    if (!Array.isArray(value) || value.length === 0) return renderNodes(node.alternate ?? [], context);
+    return value.map((item, index) => renderNodes(node.body, { root: context.root, value: item, index })).join("");
+  }).join("");
+}
